new:
M118 START_PRINT begin
{% if "gcode_macro WM_CHAMBER_LIGHT" in printer %}
    WM_CHAMBER_LIGHT STATE=on
{% endif %}
{% set BED = params.BED|int %}

M190 S{BED}
WIPE_NOZZLE                    # T0 is the Z reference of the whole print, wipe it once more right before the mesh
{% if adaptive_mesh_enable == True %}

gcode:
    {% if printer["gcode_macro _WM_PAUSE_STATE"].active|int == 1 and printer.print_stats.state == "paused" %}
        RESPOND MSG="The print is already paused. PAUSE ignored"
    {% else %}
    SET_GCODE_VARIABLE MACRO=_WM_PAUSE_STATE VARIABLE=active VALUE=1
    RESPOND MSG="Print paused. Parking the tool head."


# keep the tool map of this print for RESUME (only once START_PRINT is done: it changes box_modify_t0 for a moment)
{% if printer["gcode_macro START_PRINT"].print_body_ready %}
    {% for i in range(4) %}
        SAVE_VARIABLE VARIABLE=box_modify_t{i}_backup VALUE={printer.save_variables.variables["box_modify_t%d" % i]|default(i)|int}
    {% endfor %}
{% endif %}
# restore the identity mapping first, then turn heaters off, so that when remapped M104 Tx does not miss or wrongly switch off a physical head

M106 P2 S0
SET_STEPPER_ENABLE STEPPER={printer.toolhead.extruder} ENABLE=0
{% endif %}

gcode:
    {% if printer.print_stats.state != "paused" %}
        RESPOND MSG="Nothing to resume. The print is not paused"
    {% else %}
    RESPOND MSG="Resuming the print. Heating the bed and nozzles first."

M24
SET_GCODE_VARIABLE MACRO=_WM_PAUSE_STATE VARIABLE=active VALUE=0
{% if pr_ace %}

    # { action_respond_info("SET GCODE OFFSET X:%6f Y:%6f Z:%6f" % (offset_x, offset_y, offset_z)) }
    {% set sv = printer.save_variables.variables %}
    {% set trim = sv.wm_z_trim_all|default(0)|float + sv["wm_z_trim_t%d" % tool]|default(0)|float %}
    {% set ename = "extruder" if tool == 0 else "extruder%d" % tool %}
    {% set target = printer[ename].target|float if ename in printer else 0 %}
    {% set growth = sv.wm_nozzle_growth|default(0)|float %}
    {% set ref = sv.wm_z_ref_temp|default(140)|float %}
    {% set heat = growth * (target - ref) if (growth > 0 and target > ref) else 0 %}
    SET_GCODE_OFFSET X={offset_x} Y={offset_y} Z={(offset_z + trim + heat)|round(5)} move=1
{% endif %}

old:
    # { action_respond_info("SET GCODE OFFSET X:%6f Y:%6f Z:%6f" % (offset_x, offset_y, offset_z)) }
    SET_GCODE_OFFSET X={offset_x} Y={offset_y} Z={offset_z} move=1
{% endif %}

